package io.github.gfander.dualforge;
import java.nio.file.*;import java.util.*;import java.util.jar.JarFile;import java.util.function.Consumer;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public final class PermissionContract {
 static int assertions;static Map<String,byte[]> source;static String id,entry,net,packet,base,rich,record,rules,context,config;static final Map<String,byte[]> host=new HashMap<>();
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);assertions++;}
 static Map<String,byte[]> load(Path path)throws Exception{Map<String,byte[]> out=new TreeMap<>();try(JarFile jar=new JarFile(path.toFile())){for(var e:jar.stream().filter(x->x.getName().endsWith(".class")).toList())out.put(e.getName().replace(".class",""),jar.getInputStream(e).readAllBytes());}return out;}
 static ForgeDualBusPlan plan(Map<String,byte[]> raw){return ForgeDualBusPlan.validate(id,id,entry,raw,host::get);}
 static ClassNode node(String name){return ForgeDualBusPlan.read(source.get(name));}
 static Map<String,byte[]> changed(String name,Consumer<ClassNode> action){Map<String,byte[]> raw=new TreeMap<>(source);ClassNode n=node(name);action.accept(n);raw.put(name,ForgeDualBusPlan.bytes(n));return raw;}
 static void reject(String label,Map<String,byte[]> raw,String expected){Map<String,String> before=new TreeMap<>();raw.forEach((k,v)->before.put(k,ForgeDualBusPlan.digest(v)));try{plan(raw);throw new AssertionError("accepted "+label);}catch(IllegalStateException e){check(e.getMessage().contains(expected),label+" got="+e);System.out.println("NEGATIVE "+label+" => "+e.getMessage());}check(raw.entrySet().stream().allMatch(e->ForgeDualBusPlan.digest(e.getValue()).equals(before.get(e.getKey()))),"rejected inputs untouched");}
 static MethodNode named(ClassNode n,String name){return n.methods.stream().filter(m->m.name.equals(name)).findFirst().orElseThrow();}
 static void rename(ClassNode n,String from,String to){boolean exists=false;for(var m:n.methods)for(var op:m.instructions)if(op instanceof MethodInsnNode call && call.name.equals(from)){call.name=to;exists=true;}check(exists,"mutation exists "+from);}
 static void append(MethodNode m,String owner,String name){m.instructions.insertBefore(ForgeRegistryTransformationPlan.ops(m).getLast(),new MethodInsnNode(Opcodes.INVOKESTATIC,owner,name,"()V",false));m.maxStack+=4;}
 public static void main(String[] args)throws Exception{
  for(Path jar:Files.walk(Path.of(args[2])).filter(p->p.toString().endsWith(".jar")).toList())try(JarFile zip=new JarFile(jar.toFile())){for(var e:zip.stream().filter(e->e.getName().startsWith("net/neoforged/") && e.getName().endsWith(".class")).toList())host.put(e.getName().replace(".class",""),zip.getInputStream(e).readAllBytes());}
  Path abi=Path.of(args[3]);for(Path p:Files.walk(abi).filter(p->p.toString().endsWith(".class")).toList())host.put(abi.relativize(p).toString().replace(".class",""),Files.readAllBytes(p));
  for(int which=0;which<2;which++){
   source=load(Path.of(args[which]));id=which==0?"gatealpha":"gatebeta";String pkg="org/example/"+id+"/";entry=pkg+"Entry";net=pkg+"Network";packet=pkg+"UpTuple";rich=pkg+"UpWords";base=pkg+"BasePacket";record=pkg+"TransferData";rules=pkg+"AccessRules";context=pkg+"BusinessContext";config=pkg+"ISettings";
   ForgeDualBusPlan p=plan(source);check(source.size()==22 && p.targets().size()==8 && p.network.closure.readOnly.size()==14,"eight targets/fourteen read-only source dependencies");check(p.network.payloads.size()==3 && p.network.closure.permission && p.configType.equals("SERVER"),"three server permission definitions and bound server configuration");
   for(var row:source.entrySet()){ClassNode input=node(row.getKey());byte[] before=ForgeDualBusPlan.bytes(input);if(!p.targets().contains(row.getKey())){try{p.transform(input,null);throw new AssertionError("readonly rewritten");}catch(IllegalStateException e){check(e.getMessage().contains("UNCLAIMED_CLASS_MODIFIED"),"readonly guard");}continue;}p.transform(input,HexFormat.of().parseHex(ForgeDualBusPlan.digest(row.getValue())));check(Arrays.equals(before,ForgeDualBusPlan.bytes(input)),"clone only");try{p.transform(input,new byte[32]);throw new AssertionError("wrong SHA");}catch(IllegalStateException e){check(e.getMessage().contains("INPUT_SHA_CHANGED"),"SHA guard");}}
   reject("UNKNOWN_PERMISSION_API",changed(rules,n->rename(n,"isCreative","unverifiedCreative")),"isCreative");
   reject("UNVERIFIED_PERMISSION_PREDICATE",changed(rules,n->append(named(n,"allowed"),"java/lang/System","gc")),"UNKNOWN_CONSTRUCTOR_EFFECT");
   reject("WRONG_PERMISSION_METHOD_DESCRIPTOR",changed(rules,n->named(n,"allowed").desc=named(n,"allowed").desc.replace("world/entity/player/Player","server/level/ServerPlayer")),"MISSING_METHOD");
   reject("WRONG_PLAYER_SOURCE",changed(net,n->rename(n,"getSender","uncheckedPlayer")),"getSender");
   reject("WRONG_SERVER_AUTHORITY",changed(rules,n->rename(n,"getServer","unverifiedServer")),"getServer");
   reject("WRONG_CONFIG_OWNER",changed(context,n->{for(var op:named(n,"record").instructions)if(op instanceof MethodInsnNode m && m.owner.equals(rules))m.desc=m.desc.replace("ISettings","ForeignConfig");}),"PERMISSION_CHECK_REMOVED");
   reject("WRONG_CONFIG_VALUE_SOURCE",changed(rules,n->rename(n,"enabled","secondary")),"WRONG_CONFIG_VALUE_SOURCE");
   reject("UNVERIFIED_CLIENT_PERMISSION",changed(context,n->{for(var op:named(n,"record").instructions)if(op instanceof MethodInsnNode m && m.owner.equals(rules))m.owner=pkg+"ClientClaims";}),"CROSS_MODFILE_CONFLICT");
   reject("UNVERIFIED_SERVER_SIDE",changed(pkg+"Settings",n->{for(var m:n.methods)for(var op:m.instructions)if(op instanceof FieldInsnNode f && f.name.equals("SERVER"))f.name="CLIENT";}),"UNVERIFIED_SERVER_SIDE");
   reject("WRONG_PERMISSION_THREAD",changed(net,n->rename(n,"enqueueWork","runUnchecked")),"enqueueWork");
   reject("UNVERIFIED_PERMISSION_CACHE",changed(rules,n->n.fields.add(new FieldNode(Opcodes.ACC_PRIVATE|Opcodes.ACC_STATIC,"cached","Z",null,null))),"UNVERIFIED_PERMISSION_CACHE");
   reject("PERMISSION_BRANCH_REVERSED",changed(rules,n->{for(var op:named(n,"allowed").instructions)if(op instanceof JumpInsnNode j){j.setOpcode(Opcodes.IFNE);break;}}),"WRONG_EVENT_DOMAIN");
   reject("PERMISSION_CHECK_REMOVED",changed(context,n->{MethodNode m=named(n,"record");for(var op:m.instructions.toArray())if(op instanceof MethodInsnNode call && call.owner.equals(rules)){m.instructions.insertBefore(op,new InsnNode(Opcodes.POP2));m.instructions.set(op,new InsnNode(Opcodes.ICONST_1));}}),"PERMISSION_CHECK_REMOVED");
   reject("PERMISSION_CHECK_BYPASSED",changed(context,n->{MethodNode m=named(n,"record");for(var op:m.instructions.toArray())if(op instanceof JumpInsnNode j && j.getOpcode()==Opcodes.IFEQ){m.instructions.insertBefore(op,new InsnNode(Opcodes.POP));j.setOpcode(Opcodes.GOTO);break;}}),"WRONG_EVENT_DOMAIN");
   reject("UNVERIFIED_INVENTORY_MUTATION",changed(packet,n->append(named(n,"process"),"unverified/Inventory","mutate")),"UNKNOWN_BUSINESS_SIDE_EFFECT");
   reject("INVALID_ITEMSTACK_SOURCE",changed(rich,n->{for(var m:n.methods)for(var op:m.instructions)if(op instanceof FieldInsnNode f && f.owner.equals(ForgeRichCodecPlan.STACK) && f.name.equals("STREAM_CODEC"))f.name="OPTIONAL_STREAM_CODEC";}),"UNSUPPORTED_ITEMSTACK_CODEC");
   reject("INVALID_SLOT_SOURCE",changed(record,n->{for(var op:named(n,"source").instructions)if(op instanceof FieldInsnNode f)f.name="target";}),"UNKNOWN_BUS_ORIGIN");
   reject("UNVERIFIED_PACKET_RESPONSE",changed(context,n->append(named(n,"record"),"unverified/Response","send")),"UNKNOWN_CONSTRUCTOR_EFFECT");
   reject("UNKNOWN_PROCESS_SIDE_EFFECT",changed(packet,n->{MethodNode m=new MethodNode(Opcodes.ACC_PUBLIC,"unknownBusiness","()V",null,null);m.instructions.add(new InsnNode(Opcodes.RETURN));m.maxLocals=1;n.methods.add(m);}),"UNKNOWN_BUSINESS_SIDE_EFFECT");
   reject("UNSUPPORTED_BOOTSTRAP",changed(rules,n->{for(var m:n.methods)for(var op:m.instructions)if(op instanceof InvokeDynamicInsnNode d)d.bsm=new Handle(Opcodes.H_INVOKESTATIC,"foreign/Bootstrap","call",d.bsm.getDesc(),false);}),"UNSUPPORTED_BOOTSTRAP");
   reject("PARTIAL_CONSTRUCTOR_PLAN",changed(entry,n->named(n,"<init>").instructions.insertBefore(named(n,"<init>").instructions.getLast(),new InsnNode(Opcodes.NOP))),"UNKNOWN_CONSTRUCTOR_EFFECT");
   reject("PARTIAL_NETWORK_PLAN",changed(context,n->append(named(n,"record"),"java/lang/System","gc")),"UNKNOWN_CONSTRUCTOR_EFFECT");
   Map<String,byte[]> missing=new TreeMap<>(source);missing.remove(rules);reject("MISSING_PERMISSION_SOURCE",missing,"CROSS_MODFILE_CONFLICT");
   try{p.rejectForeignClasses(Set.of(rules));throw new AssertionError("foreign readonly utility");}catch(IllegalStateException e){check(e.getMessage().contains("CROSS_MODFILE_CONFLICT"),"owner conflict");System.out.println("NEGATIVE CROSS_MODFILE_CONFLICT => "+e.getMessage());}
   check(!plan(changed(rules,n->named(n,"<init>").instructions.insert(new InsnNode(Opcodes.NOP)))).fingerprint.equals(p.fingerprint),"read-only permission utility bytes contribute to entire plan fingerprint");System.out.println("READONLY_PERMISSION_SHA_BINDING_PASS original utility is not a transform target");
   System.out.println("NEGATIVE INPUT_SHA_CHANGED => all eight targets checked; all sources fingerprinted");System.out.println("NEGATIVE UNCLAIMED_CLASS_MODIFIED => fourteen read-only dependencies rejected");
   byte[] originalHost=host.get(ForgePermissionPlan.STACK);host.put(ForgePermissionPlan.STACK,new byte[1]);try{plan(source);throw new AssertionError("host ABI unknown");}catch(IllegalStateException e){check(e.getMessage().contains("UNVERIFIED_HOST_PERMISSION_ABI"),"native ABI guard");System.out.println("NEGATIVE UNVERIFIED_HOST_PERMISSION_ABI => "+e.getMessage());}finally{host.put(ForgePermissionPlan.STACK,originalHost);}
   System.out.println("PERMISSION_PLAN_POSITIVE owner="+id+" targets=8 readonly=14 definitions=3 scope=STATIC_BYTECODE");
  }
  Map<String,ClassNode> original=new TreeMap<>();load(Path.of(args[4])).forEach((k,v)->original.put(k,ForgeDualBusPlan.read(v)));String util="mezz/jei/common/util/ServerCommandUtil",cfg="mezz/jei/common/config/IServerConfig",deleted="mezz/jei/common/network/packets/PacketDeletePlayerItem";
  var predicate=ForgePermissionPlan.verify(original.get(util),"hasPermissionForCheatMode",cfg,original);check(predicate.methods().size()==5 && predicate.getters().size()==3,"complete four-method predicate plus clinit");
  var payload=ForgeDerivedPayloadPlan.inspect(original.get(deleted),"jei",original);try{ForgeDerivedPayloadPlan.process(payload,original);throw new AssertionError("inventory approved");}catch(IllegalStateException e){check(e.getMessage().contains("UNVERIFIED_PLAYER_INVENTORY") && e.getMessage().contains("permission=STATIC_VERIFIED"),"original inventory gate after proved permission");System.out.println("NEGATIVE UNVERIFIED_PLAYER_INVENTORY => "+e.getMessage());}
  rename(original.get(util),"isCreative","unverifiedCreative");try{ForgeDerivedPayloadPlan.process(payload,original);throw new AssertionError("unknown original predicate approved");}catch(IllegalStateException e){check(e.getMessage().contains("UNVERIFIED_PERMISSION_CHECK"),"unknown actual predicate stays rejected");System.out.println("NEGATIVE UNVERIFIED_PERMISSION_CHECK => "+e.getMessage());}
  System.out.println("PERMISSION_PLAN_PASS assertions="+assertions+" scope=STATIC_SOURCE_AND_HOST; REAL_CONNECTED_PLAYER=NOT_RUN");
 }
}
